package main

import (
	"bufio"
	"fmt"
	"os"
)

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var HPY, ATKY, DEFY int
	var HPM, ATKM, DEFM int
	var h, a, d int

	fmt.Fscan(in, &HPY, &ATKY, &DEFY)
	fmt.Fscan(in, &HPM, &ATKM, &DEFM)
	fmt.Fscan(in, &h, &a, &d)

	const INF = int(1e9)
	ans := INF

	// Upper bounds for search
	// ATK: need at least DEFM+1 to damage monster, plus some margin
	for atk := 1; atk <= 200; atk++ {
		for def := 0; def <= 200; def++ {
			damageToMonster := max(0, atk-DEFM)
			if damageToMonster == 0 {
				continue
			}
			damageToYang := max(0, ATKM-def)

			// Rounds to kill monster
			roundsToKill := (HPM + damageToMonster - 1) / damageToMonster

			// HP needed so Yang survives
			var neededHP int
			if damageToYang == 0 {
				neededHP = 1
			} else {
				neededHP = damageToYang*(roundsToKill-1) + 1
			}

			if neededHP < HPY {
				neededHP = HPY
			}

			addHP := neededHP - HPY
			addATK := atk - ATKY
			addDEF := def - DEFY

			if addHP < 0 {
				addHP = 0
			}
			if addATK < 0 {
				addATK = 0
			}
			if addDEF < 0 {
				addDEF = 0
			}

			cost := addHP*h + addATK*a + addDEF*d
			if cost < ans {
				ans = cost
			}
		}
	}

	fmt.Println(ans)
}

